mapper.select:
SELECT COUNT(*)
FROM group_member_permission
WHERE group_id       = #{groupId}
  AND user_key        = #{userKey}
  AND permission_type = #{permissionType}
  AND is_allowed      = 1

SELECT is_allowed
FROM group_member_permission
WHERE group_id       = #{groupId}
  AND user_key        = #{userKey}
  AND permission_type = #{permissionType}
LIMIT 1

mapper.insert:
INSERT INTO group_member_permission (group_id, user_key, permission_type, is_allowed, granted_by_user_key)
VALUES (#{groupId}, #{userKey}, #{permissionType}, 1, #{grantedBy})
ON DUPLICATE KEY UPDATE is_allowed = 1, granted_by_user_key = #{grantedBy}

mapper.delete:
DELETE FROM group_member_permission
WHERE group_id       = #{groupId}
  AND user_key        = #{userKey}
  AND permission_type = #{permissionType}

mapper.select:
SELECT permission_type
FROM group_member_permission
WHERE group_id  = #{groupId}
  AND user_key  = #{userKey}
  AND is_allowed = 1
